#include <Arduino.h>

const int SENS_PIN = A0; // S1
const int BUZZ_PIN = 2;  // S2

void setup() {
  pinMode(BUZZ_PIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  int val = analogRead(SENS_PIN);
  Serial.println(val);
  if (val < 400) {
    digitalWrite(BUZZ_PIN, HIGH);
    delay(1000);
    digitalWrite(BUZZ_PIN, LOW);
  } else {
    digitalWrite(BUZZ_PIN, LOW);
  }
  delay(200);
}
